mapper.select:
select user_id, post_id from sys_user_post where user_id in
#{userId}
order by user_id, post_id

mapper.insert:
insert into sys_user_post (user_id, post_id)
select #{userId}, #{postId} from dual
where not exists (
	select 1 from sys_user_post where user_id = #{userId} and post_id = #{postId}
)
